create table public.activity_feed (id uuid default gen_random_uuid() not null, user_id uuid not null, event_type text not null, client_name text, client_phone text, description text not null, metadata jsonb default '{}'::jsonb, created_at timestamp with time zone default now());
create table public.billing_credits (id uuid default gen_random_uuid() not null, user_id uuid not null, kind text not null, amount integer not null, referral_id uuid, note text, created_at timestamp with time zone default now() not null, redeemed_at timestamp with time zone);
create table public.booking_reminders (id uuid default gen_random_uuid() not null, booking_id uuid not null, reminder_type text not null, sent_at timestamp with time zone default now() not null);
create table public.bookings (id uuid default gen_random_uuid() not null, user_id uuid not null, service_id uuid not null, customer_phone text not null, booking_time timestamp with time zone not null, status text default 'confirmed'::text not null, created_at timestamp with time zone default now() not null, source text default 'direct'::text, group_id uuid);
create table public.client_sessions (id uuid default gen_random_uuid() not null, user_id uuid not null, phone_number text not null, token_hash text not null, kind text not null, verified boolean default false not null, display_name text, expires_at timestamp with time zone not null, last_used_at timestamp with time zone, created_at timestamp with time zone default now() not null);
create table public.contacts (user_id uuid not null, caller_phone text not null, name text, created_at timestamp with time zone default now(), notes text);
create table public.link_clicks (click_id uuid default gen_random_uuid() not null, call_id uuid, clicked_at timestamp with time zone default now());
create table public.loyalty_rewards (id uuid default gen_random_uuid() not null, user_id uuid not null, client_phone text not null, booking_id uuid not null, visit_key text not null, amount_cents integer default 500 not null, cut_number integer not null, created_at timestamp with time zone default now() not null);
create table public.message_templates (id uuid default gen_random_uuid() not null, user_id uuid, template_key text not null, custom_message text not null, custom_message_es text, custom_message_pt text, updated_at timestamp with time zone default now() not null);
create table public.missed_calls (id uuid default gen_random_uuid() not null, user_id uuid not null, from_number text not null, received_at timestamp with time zone default now() not null, was_opted_in boolean not null, sms_dispatched boolean default false not null, suppressed_reason text, call_sid text);
create table public.missed_calls_log (call_id uuid default gen_random_uuid() not null, user_id uuid, caller_phone text not null, barber_phone text not null, "timestamp" timestamp with time zone default now() not null, status text default 'logged'::text not null, followed_up boolean default false, last_message_at timestamp with time zone, client_language text default 'en'::text);
create table public.opt_outs (user_id uuid not null, caller_phone text not null, opted_out_at timestamp with time zone default now() not null, reason text);
create table public.phone_numbers (phone text not null, twilio_sid text, area_code text, assigned_user_id uuid, assigned_at timestamp with time zone, released_at timestamp with time zone, created_at timestamp with time zone default now() not null);
create table public.portfolio_photos (id uuid default gen_random_uuid() not null, user_id uuid not null, storage_path text not null, url text not null, width integer, height integer, sort_order integer default 0 not null, created_at timestamp with time zone default now() not null, thumb_url text, thumb_path text);
create table public.referrals (id uuid default gen_random_uuid() not null, referrer_user_id uuid not null, referred_user_id uuid not null, code text not null, status text default 'signed_up'::text not null, created_at timestamp with time zone default now() not null, qualified_at timestamp with time zone);
create table public.services (id uuid default gen_random_uuid() not null, user_id uuid not null, name text not null, price numeric(10,2) not null, duration_minutes integer default 30 not null, is_active boolean default true not null, sort_order integer default 0 not null, created_at timestamp with time zone default now() not null);
create table public.short_links (code text not null, target text not null, created_at timestamp with time zone default now() not null);
create table public.sms_log (id uuid default gen_random_uuid() not null, user_id uuid not null, to_number text not null, template_key text, language text, body text not null, status text default 'pending'::text not null, twilio_sid text, error text, created_at timestamp with time zone default now() not null, sent_at timestamp with time zone, direction text default 'outbound'::text not null, from_number text);
create table public.sticker_codes (code text not null, owner_user_id uuid, status text default 'unclaimed'::text not null, claimed_at timestamp with time zone, created_at timestamp with time zone default now() not null, batch_label text, tracking_number text, shipped_at timestamp with time zone, handed_out_at timestamp with time zone, handed_to text, handed_out_by uuid);
create table public.sticker_scans (id uuid default gen_random_uuid() not null, code text not null, scanned_at timestamp with time zone default now() not null, ip text, user_agent text);
create table public.users (user_id uuid default gen_random_uuid() not null, phone_number text, forwarding_number text, custom_message text default 'Cutting rn, need a cut? Reply YES or NO. Reply STOP to opt out.'::text not null, is_active boolean default true not null, booking_link text, business_hours jsonb, email text, avg_booking_value numeric default 35, created_at timestamp with time zone default now(), onboarding_completed boolean default false, business_name text, after_hours_message text, returning_message text, followup_message text, timezone text default 'America/New_York'::text not null, shipping_address jsonb, tracking_number text, tracking_carrier text default 'usps'::text, shipped_at timestamp with time zone, delivered_at timestamp with time zone, trial_starts_at timestamp with time zone, trial_ends_at timestamp with time zone, has_payment_method boolean default false not null, is_locked_out boolean default false not null, google_review_url text, first_name text, accent_color text default '#D4AF7A'::text, barber_language text default 'en'::text not null, avatar_url text, feature_autotext boolean default true, feature_wednesday boolean default true, feature_reviews boolean default false, rebook_interval_days smallint default 18 not null, winback_offer text, plan text default 'basic'::text not null, slug text, theme text default 'gold'::text not null, feature_marketing boolean default false not null, sticker_requested_at timestamp with time zone, referral_code text, referred_by uuid, referral_source text, call_mode text default 'forwarded'::text not null, missed_call_style text default 'casual'::text not null, carrier text, loyalty_enabled boolean default true not null, loyalty_reward_cents integer default 500 not null);
create table public.vip_clients (id uuid default gen_random_uuid() not null, user_id uuid not null, phone_number text not null, opted_in_at timestamp with time zone, first_name text, is_opted_in boolean default false not null, opted_out_at timestamp with time zone, opt_in_source text, opt_in_ip text, opt_in_user_agent text, consent_text text, client_language text default 'en'::text not null, cut_count integer default 0 not null, has_claimed_onboarding_discount boolean default false not null, last_cut_date date, last_reengagement_sent_at timestamp with time zone, first_message_sent_at timestamp with time zone, last_review_request_at timestamp with time zone, reengagement_stage smallint default 0 not null, reengagement_index smallint default 0 not null, has_claimed_winback boolean default false not null);
create table public.visit_closeouts (visit_key text not null, user_id uuid not null, client_phone text not null, closed_at timestamp with time zone default now() not null);
